local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[400503]=b({e[17034],400503,2,5,30,false,false,2,"deco/character/xiangyuanwu_haitanpaidui",false,false,false,false,false,false,false,"0",1943,873,400,1398,653,1514,2563,1398,653,1514,1180,false,false,false,false,false,false,false,false,false,false,false,false,"xiangyuanwu_xr",false,0},h)g[400504]=b({e[17034],400504,6,26,31,"「旦那様が時間を作って舞と一緒に過ごしてくださるなんて、舞はとても嬉しいです。なので、今回は特別に、普段したことのない装いに挑戦してみたのですが……旦那様、に、似合うでしょうか？」",false,2,"deco/character/xiangyuanwu_CJ",false,false,1,false,false,false,false,"0",1876,852,400,1242,803,1662,2465,1242,803,1662,1009,false,false,false,false,false,false,false,false,false,false,false,false,"xiangyuanwu_cj",false,0},h)g[400505]=b({e[23034],400505,3,27,32,"「え、獲物、ですか？　舞のことはいつでも旦那様の思うままに……。違う？　旦那様の方が、獲物？　それはちょっと予想外でした……。で、では、旦那様。舞から……舞から行きますね……！」",false,2,"deco/character/400505",false,false,1,false,false,false,false,"0",false,false,false,false,"-280,0,1","-270,0,1",2162,898,380,1017,802,2077,2184,1017,802,2077,1046,1,3330,5000,1705,3209,6666,6666,6666,6666,10000,8000,6666,"xiangyuanwu_ws",false,0},h)g[400506]=b({e[24034],400506,13,28,33,"「すみません、こんなはしたない姿をお見せしてしまい……そ、それより、ここの温泉は、心身を清め、霊力を高める効果があるそうです。牌運の向上にも繋がるかも……なので、旦那様も、試してみませんか？」",false,2,"deco/character/xiangyuanwu_WQ",false,false,1,false,false,false,false,false,false,"0,50,0.96","0,50,0.96","220,-220,1","0,50,0.96","0,50,0.96","0,0,0.96",1832,856,380,564,276,2981,2606,604,545,2901,1261,1,4520,5000,2367,2757,8000,false,13000,10666,15000,8000,8000,"xiangyuanwu_wq",false,0},h)g[400507]=b({e[21034],400507,999,29,34,false,false,3,"deco/character/xiangyuanwu_SLO",false,false,false,false,1,false,false,false,false,false,false,"240,-280,1",1868,872,398,948,421,2439,2393,948,570,2439,1261,false,false,false,false,false,false,false,false,false,false,false,false,"xiangyuanwu_slo",false,0},h)g[400508]=b({e[17045],400508,5,30,35,"「あけましておめでとうございます、旦那様。\n舞、今年は伊達巻きも手作りしてみました。最初の一口は、ぜひ旦那様に……。\nど、どうでしょうか？ お口に合いましたか？\n……良かったです。初めてだったので、失敗していないかずっと心配で……無事に出来上がったみたいで、安心しました。\nこ、これからも、新年にはこうして、旦那様におせちを用意して差し上げたいです。」",false,2,"deco/character/xiangyuanwu_yd",false,false,false,false,false,false,false,"",1,3164,5000,1627,3067,8000,8666,16666,5500,14000,8000,8000,"xiangyuanwu_yd",false,0},h)g[400509]=b({e[17045],400509,9,31,36,"「旦那様、耳を澄ませてみてください。\n窓の外、楓の葉が落ちる音まで、はっきり聞こえるでしょう？\n神様がこうして穏やかな午後のひと時を与えてくださったことですし、\n目を閉じて、少しお休みになりませんか？舞はずっと、旦那様のお傍におりますから。」",false,2,"deco/character/400509",false,false,false,false,false,false,false,"",1,3164,5000,1627,3067,8000,8666,16666,5500,14000,8000,8000,false,false,0},h)g[400601]=b({e[17023],400601,false,32,37,false,200006,false,"deco/character/fuzi",302002,60,false,false,false,false,-97,"0","50,260,0.98","50,-40,1","60,-30,1",false,false,false,"40,-30,1","0,-30,1",false,false,false,1788,780,400,1313,701,1800,2846,1313,701,1800,1039},h)g[400602]=b({e[17034],400602,1,4,38,"「バイクでツーリングに行くか、マンツーマンの麻雀コーチングか、選びな。」",200006,1,"deco/character/fuzi_0",302002,60,false,false,false,false,false,"0",1969,830,400,647,743,2373,3114,833,743,2001,1047},h)g[400603]=b({e[17034],400603,2,5,39,false,200006,2,"deco/character/fuzi_haitanpaidui",false,false,1,false,false,false,false,"0",1990,933,400,1086,817,2195,2086,1086,817,2195,1076},h)g[400604]=b({e[17034],400604,5,33,40,"「あたしが着物を着たくらいでそんなに驚くことか？　それとも何、似合わないとでも言いたいわけ？　……ふふっ、せっかくの正月だ、そんなに固くなりなさんな。ちゃんとお参りした後でツーリングに連れてってやるから、な？」",200006,2,"deco/character/fuzi_XN",false,false,false,false,false,false,false,"0",1941,867,376,933,672,2340,2838,933,672,2340,1143},h)g[400605]=b({e[22034],400605,14,34,41,"「あんた達、サクサク働きな！　今夜の宴会に間に合うかは全部あんたらにかかってるんだよ！」",200006,2,"deco/character/fuzi_YSJ",false,false,false,false,false,false,false,false,false,false,false,"80,80,0.86","0,0,0.99",1910,848,380,295,227,3526,3914,607,537,2902,1261},h)g[400606]=b({e[21034],400606,9,35,42,"「コントローラーはそっちにもあるから、適当に座って。全クリまでは……思ったよりあるね。これはそこそこ頑張ってもらわないとね、ダーリン。大丈夫、詰んだらあたしも手伝ってあげるから。それとも先に何か飲むか？」"